node -e "
const XLSX = require('xlsx');
const wb = XLSX.readFile('/workspace/testbed/data/order_summary.xlsx');

for (const sheetName of wb.SheetNames) {
  console.log('========================================');
  console.log('Sheet: ' + sheetName);
  console.log('========================================');
  const ws = wb.Sheets[sheetName];
  const range = XLSX.utils.decode_range(ws['!ref']);

  // Print header row
  const rows = XLSX.utils.sheet_to_json(ws, { header: 1, defval: '' });

  // Find max widths for formatting
  const colWidths = [];
  for (const row of rows) {
    for (let c = 0; c < row.length; c++) {
      const val = String(row[c]);
      colWidths[c] = Math.max(colWidths[c] || 0, val.length);
    }
  }

  // Print all rows with cell references
  for (let r = 0; r <= range.e.r; r++) {
    const cells = [];
    for (let c = 0; c <= range.e.c; c++) {
      const ref = XLSX.utils.encode_cell({ r, c });
      const cell = ws[ref];
      const val = cell ? (cell.w || String(cell.v)) : '';
      cells.push(ref + '=' + JSON.stringify(val));
    }
    console.log('Row ' + (r+1) + ': ' + cells.join(' | '));
  }

  console.log('');
  console.log('--- Formatted Table ---');
  const formatted = XLSX.utils.sheet_to_csv(ws);
  console.log(formatted);
  console.log('');
}
"
